#include "../src/game/stage2_extra_enemies.hpp"
#include <cassert>
int main(int argc,char**argv){if(argc!=2)return 1;shin::AssetStore assets(argv[1]);shin::IndexedSurface frame(640,480);for(int type:{0x1d,0x1e}){shin::game::Stage2ExtraEnemy e(type,200,100,assets);assert(e.payload.kind==(type==0x1d?0x68:0x69));e.tick(0,0,assets,frame);assert(e.payload.at(4)==199&&e.payload.at(8)==101);e.platform(2);e.tick(0,0,assets,frame);assert(e.payload.at(4)==200&&e.payload.at(0x68)==1);e.hurt();assert(e.sound_requests.size()==1);e.hurt();assert(e.sound_requests.size()==1);for(int i=0;i<12;++i)e.tick(0,0,assets,frame);assert(e.defeated&&e.payload.state==2);shin::game::Stage2ExtraEnemy far(type,2000,100,assets);far.tick(0,0,assets,frame);assert(far.respawn_requested&&!far.defeated);shin::game::Stage2ExtraEnemy emit(type,200,100,assets);for(int i=0;i<100;++i)emit.tick(0,0,assets,frame);assert(emit.projectiles.size()==(type==0x1e?1:0));if(type==0x1e){auto p=emit.projectiles.front();assert(p.x==emit.payload.at(4)+20&&p.y==emit.payload.at(8)+30&&p.vx==-10&&p.vy==-10&&p.callback==0x44a130);}}}
